package cl.nexbyte.siger.institucional.documental;
import cl.nexbyte.siger.institucional.nucleo.*;import java.util.*;import java.util.function.Function;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
@RestController @RequestMapping("/nucleo/ti/cuarentena-documental") @ConditionalOnProperty(name="institucional.documental.habilitada",havingValue="true")
public class CuarentenaDocumentalController {
 private final CuarentenaDocumental service;private final CatalogoLaboratorio cat;private final cl.nexbyte.siger.institucional.robustez.BaseJdbc db;
 public CuarentenaDocumentalController(CuarentenaDocumental service,CatalogoLaboratorio cat,cl.nexbyte.siger.institucional.robustez.BaseJdbc db){this.service=service;this.cat=cat;this.db=db;}
 @ModelAttribute public void privada(jakarta.servlet.http.HttpServletResponse response){response.setHeader("Cache-Control","no-store");}
 private <T>T seguro(Authentication auth,UUID id,String expected,Function<CatalogoLaboratorio.Operador,T> action){var a=SesionFuncionario.actual(auth,cat);try{if(expected!=null&&!a.id().equals(expected))throw new cl.nexbyte.siger.institucional.robustez.FalloTecnico(409,"IDENTIDAD_DE_OPERACION_CAMBIO");return action.apply(a);}catch(cl.nexbyte.siger.institucional.robustez.FalloTecnico e){if(Set.of(403,404,409).contains(e.status))db.sql.update("INSERT INTO matter_access_event(actor_id,resource_id,action_code,at_ms) VALUES(?,?,?,?)",a.id(),id==null?a.id():id.toString(),"CUARENTENA_DENEGADA",System.currentTimeMillis());throw e;}}
 @GetMapping public CuarentenaDocumental.Pagina listar(Authentication auth,@RequestParam(defaultValue="RETENIDO")String estado,@RequestParam(defaultValue="0")int pagina,@RequestParam(defaultValue="25")int limite){return seguro(auth,null,null,a->service.listar(a,estado,pagina,limite));}
 @GetMapping("/{incidente}") public CuarentenaDocumental.Incidente ver(Authentication auth,@PathVariable UUID incidente){return seguro(auth,incidente,null,a->service.ver(a,incidente));}
 @PostMapping public CuarentenaDocumental.Incidente aislar(Authentication auth,@RequestHeader("Idempotency-Key")UUID key,@RequestHeader("X-Siger-Actor")String expected,@RequestBody CuarentenaDocumental.Aislar r){return seguro(auth,r==null?null:r.documento(),expected,a->service.aislar(a,key,r));}
 @PostMapping("/{incidente}/verificar") public CuarentenaDocumental.Incidente verificar(Authentication auth,@PathVariable UUID incidente,@RequestHeader("Idempotency-Key")UUID key,@RequestHeader("X-Siger-Actor")String expected,@RequestBody CuarentenaDocumental.Verificar r){return seguro(auth,incidente,expected,a->service.verificar(a,key,incidente,r));}
}
